INSERT INTO public.chapter_translations (chapter_id, language_code, title, content)
VALUES ('e190f304-1726-4f2d-a96b-9f48655dfa39', 'bg', 'Няма къде да избягаш', $bg$<p>Тази година не беше кръчмата.</p><p>Беше Изход 44, единайсет и двайсет вечерта, в международен терминал, който можеше да е във всяка държава на земята. Някой от старата работа се женеше в Лисабон и беше поканил и Ари, и Робин, което беше или акт на любов, или акт на война. Полетът беше закъснял два пъти. Таблото с излитанията все разбъркваше часа като крупие, което не иска никой да спечели.</p><p>Изходът беше претъпкан. Бизнесмени с разхлабени вратовръзки. Семейство с три деца, заспали върху купчина палта. Двама туристи с раници, които сравняваха татуировките си. Чистач, който водеше машина за под в бавни, безкрайни кръгове покрай безмитен магазин, продаващ същия шоколад, същия парфюм и същото уиски като всеки безмитен магазин на планетата.</p><p>Робин пишеше. Ари четеше през рамото на Робин.</p><p>Снимка на пистата през нощта, размазани светлини през стъкло. Надпис: <em>Летя с натежало сърце, знаейки какво причинява това на планетата ни. Трябва да станем по-добри. 🌍</em></p><p>Публикувано. Телефонът – долу.</p><p>„Недей – каза Робин.“</p><p>„Нищо не казах.“</p><p>„Вече зареждаше.“</p><p>„Четях. За кого е?“</p><p>„Какво?“</p><p>„Постът. За кого е? Не за планетата. Планетата няма Инстаграм.“</p><p>„Това е повишаване на осведомеността.“</p><p>„Осведоменост за какво? Че самолетите горят гориво? Назови ми един жив възрастен, който не знае, че самолетите горят гориво.“ Ари се отпусна обратно в пластмасовата седалка. „Не повишаваш осведомеността. Вдигаш ръка. «Госпожо, аз знам и ми е ужасно гузно.» Това е целият пост. Искаш признание за вината, без да платиш за самото нещо. Миналата година ти казах, че политиката ти е църква. Това е частта от църквата, която продаваше индулгенции. Плащаш монета – махаш сто дни от чистилището. Ти просто плати с постове.“</p><p>Тази година Робин нямаше нужда от загрявка.</p><p>„Знаеш ли кое е по-евтино от пост? Подигравката. Аз поне казвам нещо. А ти всеки път седиш и гледаш отвисоко. Това също е сигнал, Ари. Въртенето на очи е сигнал. Физиономията «аз съм над всичко това» е най-самодоволният сигнал за добродетел, който съществува. Просто го изпълняваш пред друга публика.“</p><p>Ари дълго гледа Робин.</p><p>„Това е добро. Това е истински удар. Личи си, че се упражняваш.“</p><p>„Имах цяла година.“</p><p>„Така е. Презрението също е костюм.“ Ари сви рамене. „Разликата е, че аз не се преструвам, че моето е за някой друг. Моята подигравка е за мен. Твоят пост твърди, че е за планетата.“</p><p>Робин отново отвори приложението, сякаш постът имаше нужда от охрана. Ари продължи.</p><p>„Знаеш ли защо опашката на пауна изобщо означава нещо?“</p><p>„О, започна се.“</p><p>„Защото е скъпа. Тежка е. Ярка е. Забавя го и лисиците го изяждат. Пауницата гледа това нелепо нещо и си мисли: щом оцелява, като го влачи насам-натам, сигурно е силен. Сигналът е честен, защото му струва нещо. Биолозите имат име за това. Скъпо сигнализиране. И правилото е просто. Сигнал, който не струва нищо, не ти казва нищо.“ Ари кимна към екрана. „Този пост не ти струваше нищо. Той ти плати. Трийсет и едно харесвания.“</p><p>Робин погледна надолу. Трийсет и четири.</p><p>„Тогава кое се брои? В идеалния свят на Ари.“</p><p>„Всичко, което струва. Човекът, който стана на събрание, каза истината и го уволниха заради нея – от която и страна да е била истината. Жената от моята улица, която за двайсет години е приела в дома си единайсет деца и никога не е публикувала нито една тяхна снимка. Старецът, който всеки вторник кара съседа си на химиотерапия. Това са добродетели. Никога няма да ги видиш онлайн, защото хората, които ги вършат, са твърде заети да ги вършат.“</p><p>Робин замълча. После:</p><p>„Когато бях на петнайсет, в моето село имаше един магазин със стикер с дъга в ъгъла на витрината. Мъничък. Почти избелял от слънцето. Три години купувах от този магазин всичко, което можех. Този стикер беше единственото нещо в цялото село, което ми казваше, че не съм само аз.“ Гласът на Робин вече имаше острота. „Така че не смей да ми казваш, че сигналите нямат стойност.“</p><p>Ари не отговори веднага.</p><p>„Няма – каза Ари. – Защото този стикер струваше нещо. В онова село, в онази година, човекът, който го е сложил, е губил клиенти заради него. Вероятно поне веднъж са му счупили витрината с тухла. Това е опашка на паун. Това е истинското нещо.“ Пауза. „А сега го сравни с банката, която всеки юни в Лондон прави логото си на дъга и някак забравя да го направи в профилите си за държавите, където това би ѝ струвало пари. Същото знаме. Едното е добродетел. Другото е маркетингов календар.“</p><p>Робин отвори уста, после я затвори.</p><p>От другата страна на пътеката мъж с елек и малка нашивка с националното знаме на раницата слушаше от известно време. Наведе се, доволен от себе си.</p><p>„Все тия уоук компании, нали. Станеш ли уоук – фалираш.“</p><p>Ари се обърна. „На раницата ти има знаме.“</p><p>„И?“</p><p>„И какво ти струваше? Проля ли кръв за него? Загуби ли работа заради него? Не. Купи го от крайпътна бензиностанция за четири паунда. Същото е като логото на дъга. Различни цветове. Ти си паун с нашивка на велкро.“</p><p>Мъжът погледна собствената си раница, сякаш го беше предала. Двамата туристи с раниците се разсмяха на глас.</p><p>Робин промърмори „благодаря“, без да иска.</p><p>„Не ми благодари – каза Ари. – Същото щях да кажа и на теб. Току-що го казах.“</p><p>---</p><p>Високоговорителят над тях изпращя.</p><p><em>Дами и господа, със съжаление ви съобщаваме, че полетът за Лисабон вече се очаква да излети в един и петнайсет. Ваучери за закуски можете да получите на гишето.</em></p><p>Четирийсет души изпъшкаха едновременно на около единайсет различни езика. Беше, някак, абсолютно едно и също пъшкане.</p><p>Робин отиде до гишето и се върна с два сандвича в еднакви триъгълни кутийки.</p><p>„Пилешко – каза Робин и подаде единия. – Или, ако предпочиташ, пилешко.“</p><p>Ари обърна кутийката. Същата марка, която можеш да си купиш на всяко летище оттук до Сеул.</p><p>„Това – каза Ари – е следващата ми точка.“</p><p>„Разбира се, че е.“</p><p>„Огледай се. Кажи ми в коя държава сме.“</p><p>Робин се огледа. Кафе веригата. Рекламата на парфюм с модел, разочарован от всички. Книжарницата, която продава същите десет книги като всяка летищна книжарница по света. Поп песен, която се носеше от тавана, която всички знаеха и никой не беше избрал.</p><p>„Не можеш, нали? – каза Ари. – Ако ти вържат очите, закарат те до Франкфурт, Дубай или Сингапур и ти махнат превръзката в терминала, ще трябва да намериш табела на местния език, за да познаеш. А половината от тях са на английски.“</p><p>„Значи летищата са скучни. Голямо откритие.“</p><p>„Не са летищата. Всичко е. Когато бях дете отзад в онзи бус, светът беше огромен. Всяка граница беше различна планета. Различна храна. Различна музика. Различни начини да си груб, различни начини да си добър. И ни обещаха, че ако съборим стените, светът ще се отвори. Това беше думата. Хоризонти. Разшири хоризонтите си.“ Ари остави сандвича на празната седалка. „И събориха стените. А хоризонтът не се разшири. Приближи се. Защото когато всичко е еднакво навсякъде, вече няма «някъде другаде». Светът не стана по-голям. Превърна се в една стая. И стените на тази стая се свиват.“</p><p>Робин отвърна рязко.</p><p>„Това е носталгия с паспорт. Глобализацията извади милиард души от бедността. Тази вечер има деца, които вечерят на места, където преди трийсет години децата умираха от глад. Ти тъгуваш за вкусове кафе, докато те са живи.“</p><p>„Не споря за икономиката. Повече храна, по-малко мъртви деца. Ще го подпиша с кръв. Говоря за това какво направи с вътрешността на хората.“</p><p>„Имам приятели в Лагос. В Сеул. Говоря с тях всеки ден. Това е хоризонт, какъвто на теб никога не ти е бил достъпен.“</p><p>„Твоят приятел в Лагос гледа същите сериали като приятеля ти в Лийдс – каза Ари. – Използва същия жаргон. Има същото мнение за същите американски избори. Води същата американска културна война със същите американски думи и бива канселиран по същите американски правила.“ Ари сви рамене. „Ти не откри Лагос. Лагос получи копие от теб. Това всъщност изнесе глобализацията. Не света при теб. А теб при света.“</p><p>Челюстта на Робин се стегна. И тогава Робин го каза.</p><p>„Прекарали са те през граница отзад в бус. Границите са това, което те държеше в ада. Не седи там да романтизираш стените. Не ти. Точно ти – не.“</p><p>Това беше най-тежкото нещо, изричано някога от Робин срещу Ари през масата. И двамата го знаеха. Единият от туристите с раниците дори трепна.</p><p>Ари не трепна.</p><p>„Не романтизирам стените. Скърбя за разстоянието. Има разлика. Стената те държи вътре. Разстоянието ти позволява да се махнеш.“ Гласът на Ари беше равен и много спокоен. „Майка ми не прекоси онази граница заради друга марка кафе. Прекоси я, защото от другата страна онова, от което бягахме, вече не можеше да ни стигне. Това беше целият смисъл. Имаше «далече».“ Ари кимна към телефона в ръката на Робин. „Следващото дете отзад в бус каца, включва това нещо и всичко още е там. Същото правителство чете съобщенията му. Същите хора пращат същите заплахи. Същото село го намира в коментарите. Вече няма изгнание. Изгнанието беше милост. Продадоха ни края на стените и ни доставиха края на разстоянието. Сега има само една стая, завинаги, с всички в нея, и всички гледат.“</p><p>Робин дълго не каза нищо.</p><p>Мъж с бейзболна шапка две седалки по-нататък, американец по акцента, се наведе напред.</p><p>„Точно така, човече. Глобалистите са. Елитите са планирали всичко това. Давос, цялата работа.“</p><p>„Никой не го е планирал – каза Ари, без да го погледне. – Плановете искат някой компетентен начело, а аз познавам хората начело. Никой не управлява. Изравняването не е конспирация. Просто е по-евтино. Това става, когато всичко се продава на всички по едно и също време. Искате злодей, защото злодеят би означавал, че някой може да го спре. Няма злодей. Има само етикет с цена.“</p><p>Мъжът нахлупи шапката си и се върна към телефона си.</p><p>---</p><p>Робин поскролва минута, със стисната челюст, после обърна екрана.</p><p>„Добре. Ето едно, което не можеш да изкривиш.“</p><p>Клип. Жена в подкаст, наведена към един от онези големи черни микрофони.</p><p><em>„Искам мъж, който поема водачеството. Който планира срещите. Който е спонтанен, който знае какво иска, който се грижи за мен. Искам да се чувствам в безопасност.“</em></p><p>Под него – коментарите. <em>Това е стандартът. Знай цената си, кралице. Никога не се примирявай с по-малко.</em></p><p>„Виждаш ли? – каза Робин. – Това е здравословно. Това е някой, който знае точно какво иска и не се срамува от това.“</p><p>Ари взе телефона. Написа нещо. Поскролва. Върна го.</p><p>Друг клип. Мъж в друг подкаст, същият голям черен микрофон.</p><p><em>„Искам жена, която ме оставя да водя. Която ме оставя да планирам нещата. Която ми има доверие да се грижа за нея.“</em></p><p>Под него: <em>Червен флаг. Иска си слугиня. Това е контролиращо поведение. Бягай, сестро.</em></p><p>„Същото изречение – каза Ари. – Огледален образ. Тя иска мъж, който води. Той иска жена, която го оставя да води. Това е една и съща връзка. Буквално една и съща връзка, описана от двата стола. Едната е кралица, която знае цената си. Другият е червен флаг.“</p><p>„Не е същото. Когато тя го казва, моли за нещо. Когато той го казва, иска власт над някого.“</p><p>„Тя моли един мъж да има власт над нея. Просто моли учтиво. Ако неговото изречение е за власт, значи и нейното е.“</p><p>Този път Робин имаше готов отговор.</p><p>„Контекстът променя значението. «Ще те изпратя до вкъщи» от приятел е доброта. От непознат в два през нощта е заплаха. Същите думи. А през по-голямата част от историята жена, омъжена за мъж, който «води», не можеше да си тръгне. В някои държави чак до седемдесетте не можеше да си открие банкова сметка без неговия подпис. Така че когато мъж каже «остави ме да водя», това носи всичко това. Не е заради него. А заради тежестта върху изречението.“</p><p>„Носеше тази тежест през 1950-а – каза Ари. – Двайсет и две годишният, който го казва днес, не е построил 1950-а. Роден е много след като е свършила. Четеш изречението му с почерка на прадядо му.“</p><p>„Властта не изчезва само защото тогава те е нямало.“</p><p>„Нито пък другата половина от сделката.“ Ари почука по екрана. „Гледай. Тя иска мъж, който се грижи за нея. Това е да знаеш цената си. Той иска жена, която се грижи за дома. Това е атака срещу правата на жените. Това е една и съща размяна. Точната уговорка от петдесетте, срязана през средата. Едната половина е овластяване, другата – потисничество, и единствената разлика е коя половина говори.“</p><p>„Защото тази сделка е била наложена на жените.“</p><p>„А другата половина е била наложена на мъжете. Момчето, което е слизало в мината на шестнайсет и на четирийсет е кашляло кръв, за да има отопление вкъщи. И то не се е записвало за своята половина. Никой не направи плакат за него. Никой не му даде подкаст.“</p><p>Робин остави телефона и потърка очи.</p><p>„Принципът е прост, Ари. Удряй нагоре, не надолу. Нападай силните, защитавай уязвимите. Това е всичко.“</p><p>„Кой решава кой е горе?“</p><p>„Това е… очевидно. Най-често.“</p><p>„Никога не е очевидно. Точно в това е номерът. Това е най-добрата вратичка, писана някога. Можеш да удряш когото си искаш, колкото силно искаш, стига първо да обявиш, че си под него. И така всички го правят. Всички са отдолу. Целият интернет е мазе, пълно с хора, които удрят нагоре един друг. Всяка група на земята се кълне, че е най-долу, защото долу е разрешението.“</p><p>Ари се облегна назад.</p><p>„Пак е писание. Обичаш писанията, просто не го знаеш. Блажени кротките, защото те ще наследят земята. Ти намери начин да превърнеш кротостта в оръжие. Първа стъпка: докажи, че си кротък. Втора стъпка: вземи земята.“</p><p>---</p><p>Вече половината изход слушаше. Бизнесмените бяха спрели да се правят, че отговарят на имейли. Майката на трите заспали деца се беше обърнала с цялото си тяло към тях. Дори чистачът беше забавил машината почти до спиране.</p><p>Млада жена с лаптоп, облепен със стикери, не издържа повече.</p><p>„Мъжете буквално не могат да изпитат сексизъм – каза тя. – Сексизмът е предразсъдък плюс власт.“</p><p>Ари се обърна към нея с нещо като интерес.</p><p>„Тогава и мъж без власт не може да е сексист.“</p><p>„Не е това…“</p><p>„Безработният деветнайсетгодишен в задната стая на майка си, който цяла нощ пише омраза към жените в интернет. Той няма никаква власт. Никаква. По вашето определение е невинен. Току-що оправдахте най-лошия мъж в интернет.“ Ари изчака миг. „Искате ли да преосмислите определението, или го запазвате?“</p><p>„Не това означава.“</p><p>„Точно това означава. Това е проблемът с определенията, създадени да печелят спорове. Рано или късно някой ги прочита.“</p><p>Тя затвори лаптопа.</p><p>От другата страна едро момче с потник и слушалки на врата беше кимало на всичко, което Ари казваше, и реши, че това е неговият момент.</p><p>„Не, ама честно, жените искат алфа мъже, брат. Биология е. Виж вълците.“</p><p>Ари въздъхна като учител в последния ден на срока.</p><p>„Историята с алфа вълка идва от изучаване на вълци в плен. Непознати, натикани заедно в кошара, които се бият, защото нямат къде да отидат. Ученият, който я направи прочута, прекара следващите няколко десетилетия да моли всички да спрат да я повтарят, защото в дивата природа глутницата е просто семейство. «Алфата» са мама и татко.“ Пауза. „Изградил си цялата си личност върху зоологическа градина.“</p><p>Целият изход се засмя. Истински. Момчето се ухили смутено и си сложи обратно слушалките.</p><p>„Ама все пак“ – измърмори то.</p><p>„Никакво все пак“ – каза Ари.</p><p>Робин вече гледаше Ари по различен начин. Не по-меко. Просто по-отблизо.</p><p>„Тогава какво всъщност искаш? Мъжете да казват каквото си искат и всички просто да кимат?“</p><p>„Не. Искам едно правило.“ Ари вдигна един пръст. „Същото изречение получава същата присъда. Съди изречението, не устата, от която е излязло. Ако «искам някой, който води» е наред, наред е и от двата стола. Ако е контролиращо, контролиращо е и от двата стола. Избери едното. Наистина не ме интересува кое. Това, което не можеш да правиш, е да държиш един закон за хората, които харесваш, и друг закон за тези, които не харесваш, и пак да го наричаш етика.“</p><p>Пауза.</p><p>„Всеки режим, който познавам отвътре, имаше един закон за нас и друг за тях. Това не е прогресивно, Робин. Това е най-старата система, която съществува.“</p><p>Робин дълго мълча. Машината за под бръмчеше. Едно от децата върху палтата се обърна в съня си.</p><p>„Първото и аз го казах – обади се накрая Робин. – На срещи. Почти дума по дума. «Искам някой, който поема нещата в свои ръце.»“</p><p>„Знам.“</p><p>„А на второто щях да плъзна нататък, без да дочета изречението.“</p><p>„Знам.“</p><p>„Откъде знаеш?“</p><p>„Защото всеки би го направил. Това е смисълът. Не си ти. Водата е. Никой не избира да е мокър.“ Ари отново взе сандвича и го огледа с дълбоко подозрение. „И не си въобразявай, че това е нещо особено. Аз и на двамата щях да плъзна нататък. Не искам да ме водят и не искам да водя. Искам да ме оставят на мира.“</p><p>---</p><p><em>Започваме качване на борда на всички редове за полета до Лисабон.</em></p><p>Целият изход се изправи едновременно и образува същата опашка, която се образува на всеки изход на всяко летище по света. Мъжът с нашивката със знамето се озова точно зад жената с облепения лаптоп. Никой от двамата не проговори. Момчето с потника помогна на майката да пренесе едно от заспалите деца по ръкава и никой не го засне, никой не го публикува, и за около деветдесет секунди това беше най-добродетелното нещо, случило се в сградата през цялата нощ.</p><p>Ари забеляза. Не каза нищо.</p><p>Имаха последните две места на ред 31. Робин взе пътеката. Ари взе прозореца, както винаги.</p><p>Самолетът се издигна. Градът се отдалечи под тях – разлято петно от оранжеви светлини, после пътища като вени, после пръснати градчета, после нищо. Само тъмнина. Огромна, неосветена тъмнина между едно място и следващото, както беше някога.</p><p>Ари дълго гледа навън.</p><p>„Хайде де – каза Робин с полузатворени очи. – Кажи нещо мрачно. Мълчиш от десет минути. Не е естествено.“</p><p>„Светът още изглежда голям оттук горе.“</p><p>Робин отвори едното си око. „Внимавай. Това почти прозвуча като надежда.“</p><p>„Изглежда голям – каза Ари, – защото оттук горе не виждаш никого в него.“</p><p>Робин се засмя толкова силно, че човекът на предната седалка се обърна с гневен поглед.</p><p>Ари все пак спусна щорката.</p>$bg$);

-- Heretics' Table (bg): close the quotation marks on three lines of dialogue.
UPDATE public.chapter_translations
   SET content = regexp_replace(content, '<p>(„[^“<]*)</p>', '<p>\1“</p>', 'g')
 WHERE chapter_id = 'e3096149-6460-40b0-aab0-e7484a84c021' AND language_code = 'bg';
